"""
Diverse prompt dataset for Activation Robustness research.

Provides a curated set of 200+ base prompts spanning multiple length classes,
intents, domains, and registers. These prompts serve as the foundation that
perturbation methods are applied to when studying representational stability.
"""

from __future__ import annotations

import json
import random
from collections import Counter
from dataclasses import dataclass, field, asdict
from typing import Optional


# ---------------------------------------------------------------------------
# Length-class boundaries (inclusive)
# ---------------------------------------------------------------------------
_LENGTH_BOUNDS = {
    "very_short": (1, 8),
    "short": (9, 20),
    "medium": (21, 50),
    "long": (51, 99),
    "extended": (100, 200),
    "very_long": (201, 500),
    "ultra_long": (501, 99999),
}


def _infer_length_class(word_count: int) -> str:
    for cls, (lo, hi) in _LENGTH_BOUNDS.items():
        if lo <= word_count <= hi:
            return cls
    return "ultra_long"


# ---------------------------------------------------------------------------
# Prompt dataclass
# ---------------------------------------------------------------------------
@dataclass
class Prompt:
    """A single base prompt with metadata."""

    text: str
    length_class: str = ""
    intent: str = ""
    domain: str = ""
    tags: list[str] = field(default_factory=list)
    word_count: int = 0

    def __post_init__(self) -> None:
        self.word_count = len(self.text.split())
        if not self.length_class:
            self.length_class = _infer_length_class(self.word_count)

    # -- serialization ------------------------------------------------------
    def to_json(self) -> dict:
        return asdict(self)

    @classmethod
    def from_json(cls, data: dict) -> Prompt:
        return cls(**data)


# ---------------------------------------------------------------------------
# PromptDataset
# ---------------------------------------------------------------------------
class PromptDataset:
    """Collection of diverse prompts with filtering and sampling."""

    def __init__(self, prompts: list[Prompt]) -> None:
        self._prompts = list(prompts)

    # -- constructors -------------------------------------------------------
    @classmethod
    def default(cls) -> PromptDataset:
        """Load the built-in diverse prompt set."""
        return cls([Prompt(**kw) for kw in _DEFAULT_PROMPTS])

    # -- filtering ----------------------------------------------------------
    def filter(
        self,
        length_class: Optional[str] = None,
        intent: Optional[str] = None,
        domain: Optional[str] = None,
        tags: Optional[list[str]] = None,
    ) -> PromptDataset:
        """Return a new dataset containing only prompts that match all given criteria."""
        result = self._prompts
        if length_class is not None:
            result = [p for p in result if p.length_class == length_class]
        if intent is not None:
            result = [p for p in result if p.intent == intent]
        if domain is not None:
            result = [p for p in result if p.domain == domain]
        if tags is not None:
            tag_set = set(tags)
            result = [p for p in result if tag_set.issubset(set(p.tags))]
        return PromptDataset(result)

    # -- sampling -----------------------------------------------------------
    def sample(
        self,
        n: int,
        seed: int = 42,
        stratify_by: Optional[str] = None,
    ) -> list[Prompt]:
        """Sample *n* prompts, optionally stratified by an attribute.

        When *stratify_by* is set (e.g. ``"intent"``), the sample draws
        roughly equal numbers from each stratum.  If *n* exceeds the
        dataset size, the full dataset is returned (shuffled).
        """
        rng = random.Random(seed)
        pool = list(self._prompts)

        if stratify_by is None:
            rng.shuffle(pool)
            return pool[:n]

        # group by attribute
        buckets: dict[str, list[Prompt]] = {}
        for p in pool:
            key = getattr(p, stratify_by)
            buckets.setdefault(key, []).append(p)

        for v in buckets.values():
            rng.shuffle(v)

        per_bucket = max(1, n // len(buckets))
        remainder = n - per_bucket * len(buckets)

        sampled: list[Prompt] = []
        bucket_keys = sorted(buckets.keys())
        for i, key in enumerate(bucket_keys):
            take = per_bucket + (1 if i < remainder else 0)
            sampled.extend(buckets[key][:take])

        rng.shuffle(sampled)
        return sampled[:n]

    # -- accessors ----------------------------------------------------------
    def texts(self) -> list[str]:
        """Return just the prompt text strings."""
        return [p.text for p in self._prompts]

    def __len__(self) -> int:
        return len(self._prompts)

    def __iter__(self):
        return iter(self._prompts)

    def __getitem__(self, idx):
        return self._prompts[idx]

    # -- summary ------------------------------------------------------------
    def summary(self) -> str:
        """Return a human-readable distribution summary."""
        total = len(self._prompts)
        lines = [f"PromptDataset: {total} prompts\n"]

        for attr in ("length_class", "intent", "domain"):
            counts = Counter(getattr(p, attr) for p in self._prompts)
            lines.append(f"  {attr}:")
            for key in sorted(counts):
                lines.append(f"    {key:15s} {counts[key]:>4d}  ({100*counts[key]/total:.1f}%)")
            lines.append("")

        return "\n".join(lines)

    # -- serialization ------------------------------------------------------
    def to_json(self) -> list[dict]:
        return [p.to_json() for p in self._prompts]

    @classmethod
    def from_json(cls, data: list[dict]) -> PromptDataset:
        return cls([Prompt.from_json(d) for d in data])


